Lemma pv_callee HL LK cr Aw M model M' HL' sp' scr' W' :
  ri_inv HI (HL ++ LB) FF LK cr Aw M (vml_of model) -> mem_ok M ->
  L5CA.ahpres L ar (HL' ++ LB) FF sp' scr' W' M M' -> sp' <= S -> PMKA.wapp W' ->
